// Interface between the runtime and recompiled SPU code (generated by ac4-spurecomp into
// local/gen/spu; game-derived, never distributed). A chunk is valid for a thread when the LS
// bytes of all its ranges equal `code`.
#pragma once
#include "common/bytes.h"

namespace rt::spu {
struct Thread;
}

namespace spu_gen {

using ChunkFn = bool (*)(rt::spu::Thread&);  // false: the SPU thread must stop

struct Chunk {
  u32 entry;
  u32 nranges;
  const u32* ranges;  // nranges (start, end) byte pairs
  const u32* code;    // the ranges' LS bytes, concatenated (u32 words in LS byte order)
  ChunkFn fn;
};

extern const Chunk g_chunks[];
extern const u32 g_chunk_count;

}  // namespace spu_gen
